  EXPECT_EQ("4.9014e+06", fmt::format("{:g}", 4.9014e6));
  EXPECT_EQ("392.650000", fmt::format("{:f}", 392.65));
  EXPECT_EQ("392.650000", fmt::format("{:F}", 392.65));
